1	package wallet
2	
3	import (
4		"errors"
5		"reflect"
6		"testing"
7		"time"
8	)
9	
10	// multiTimeoutPolicy 构造一条出资账户 payer、使用账户 u1/u2、在整个测试时间窗
11	// 内有效且开启预留超时（最长预留时长 d）的策略。
12	func multiTimeoutPolicy(c *clock, id string, d time.Duration) PolicySpec {
13		p := validPolicy(c)
14		p.ID = id
15		p.MaxPerRequest = 100
16		p.MaxTotal = 100
17		p.MaxReserveDuration = d
18		return p
19	}
20	
21	// setupMultiTimeout 构造多策略共用一个出资账户的钱包：payer（1000）、使用账户
22	// u1/u2 各自的长会话，以及出资账户用于审批的会话 sa。
23	func setupMultiTimeout(t *testing.T) (*Wallet, *clock) {
24		t.Helper()
25		w, c := newTestWallet()
26		mustAccount(t, w, "payer", 1000)
27		mustAccount(t, w, "u1", 0)
28		mustAccount(t, w, "u2", 0)
29		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(4*time.Hour)); err != nil {
30			t.Fatal(err)
31		}
32		if _, err := w.CreateSession("s2", "u2", "dev2", c.t.Add(4*time.Hour)); err != nil {
33			t.Fatal(err)
34		}
35		if _, err := w.CreateSession("sa", "payer", "dev-approve", c.t.Add(4*time.Hour)); err != nil {
36			t.Fatal(err)
37		}
38		return w, c
39	}
40	
41	// applyMulti 以对应账户的会话提交一笔申请。
42	func applyMulti(t *testing.T, w *Wallet, policyID, account, requestID string, fee int64) {
43		t.Helper()
44		in := baseApply()
45		in.PolicyID = policyID
46		in.AccountID = account
47		in.RequestID = requestID
48		in.EstimatedFee = fee
49		if account == "u2" {
50			in.SessionID, in.DeviceID = "s2", "dev2"
51		}
52		if _, err := w.Apply(in); err != nil {
53			t.Fatalf("apply %s/%s: %v", account, requestID, err)
54		}
55	}
56	
57	// 一次账本查询同时发现多笔到期预留：新增超时记录按截止时刻升序（同截止按
58	// 使用账户、请求编号升序）追加在旧账本末尾，每笔先出资账户全额退款、再使用
59	// 账户零金额超时记录，记录时间为各笔自己的截止时刻；未到期请求继续预留。
60	func TestMultiReservationTimeoutReleaseOrdering(t *testing.T) {
61		w, c := setupMultiTimeout(t)
62		save := func(p PolicySpec) {
63			t.Helper()
64			if err := w.SavePolicy(p); err != nil {
65				t.Fatal(err)
66			}
67		}
68		// 同一出资账户 payer 经不同策略代付，各策略最长预留时长不同。
69		save(multiTimeoutPolicy(c, "pa", 10*time.Second))
70		save(multiTimeoutPolicy(c, "pb", 30*time.Second))
71		save(multiTimeoutPolicy(c, "pc", 20*time.Second))
72		ap := multiTimeoutPolicy(c, "pd", 10*time.Second)
73		ap.ApprovalThreshold = 10
74		ap.ApprovalWait = 2 * time.Hour
75		save(ap)
76	
77		t0 := c.t
78		// 提交次序与截止次序刻意不同；r1/r2/r4 同号分属 u1 与 u2，不得合并。
79		applyMulti(t, w, "pc", "u2", "r9", 7)  // 截止 t0+20
80		applyMulti(t, w, "pa", "u1", "r1", 20) // 截止 t0+10
81		applyMulti(t, w, "pd", "u1", "r7", 20) // 超门槛进入待审批，批准后才起算
82		c.t = t0.Add(time.Second)
83		applyMulti(t, w, "pb", "u2", "r1", 30) // 截止 t0+31
84		c.t = t0.Add(2 * time.Second)
85		applyMulti(t, w, "pc", "u1", "r2", 15) // 截止 t0+22
86		c.t = t0.Add(3 * time.Second)
87		applyMulti(t, w, "pa", "u2", "r2", 25) // 截止 t0+13
88		c.t = t0.Add(4 * time.Second)
89		applyMulti(t, w, "pb", "u1", "r3", 10) // 截止 t0+34：首轮查询时未到期
90		c.t = t0.Add(5 * time.Second)
91		applyMulti(t, w, "pa", "u2", "r4", 5) // 截止 t0+15
92		applyMulti(t, w, "pa", "u1", "r5", 6) // 截止 t0+15
93		applyMulti(t, w, "pa", "u1", "r4", 8) // 截止 t0+15
94		c.t = t0.Add(6 * time.Second)
95		if _, err := w.Approve("u1", "r7", "sa", "dev-approve"); err != nil {
96			t.Fatalf("approve r7: %v", err)
97		} // r7 自批准成功时刻起算：截止 t0+16，等待审批的时间不计入
98	
99		// 查询前：10 笔共预留 146；账本快照含 9 条预留、1 条待审批、
100		// 1 条批准带来的预留与 1 条批准记录。
101		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 854, Reserved: 146}) {
102			t.Fatalf("balance before query = %+v, want {854 146}", bal)
103		}
104		before := w.Ledger()
105		if len(before) != 12 {
106			t.Fatalf("ledger before query = %d entries, want 12", len(before))
107		}
108	
109		// 恰为 u2/r1 的截止时刻（到达截止时刻本身即释放）：一次查询发现 9 笔到期。
110		c.t = t0.Add(31 * time.Second)
111		got := w.Ledger()
112	
113		// 查询前已有的历史记录保持原位置与内容，新增记录只追加在末尾。
114		if len(got) != len(before)+18 {
115			t.Fatalf("ledger after query = %d entries, want %d", len(got), len(before)+18)
116		}
117		if !reflect.DeepEqual(got[:len(before)], before) {
118			t.Fatal("existing ledger entries were rewritten or reordered")
119		}
120	
121		// 新增超时记录按截止时刻升序，同截止按使用账户、请求编号升序；
122		// 每笔先出资账户全额退款、紧接使用账户零金额超时记录，两条都关联请求
123		// 编号并说明原因，记录时间为该笔自己的截止时刻而非查询时刻。
124		want := []struct {
125			at      time.Time
126			account string
127			request string
128			amount  int64
129		}{
130			{t0.Add(10 * time.Second), "u1", "r1", 20},
131			{t0.Add(13 * time.Second), "u2", "r2", 25},
132			{t0.Add(15 * time.Second), "u1", "r4", 8},
133			{t0.Add(15 * time.Second), "u1", "r5", 6},
134			{t0.Add(15 * time.Second), "u2", "r4", 5},
135			{t0.Add(16 * time.Second), "u1", "r7", 20},
136			{t0.Add(20 * time.Second), "u2", "r9", 7},
137			{t0.Add(22 * time.Second), "u1", "r2", 15},
138			{t0.Add(31 * time.Second), "u2", "r1", 30},
139		}
140		var refundSum int64
141		for i, e := range want {
142			refund := got[len(before)+2*i]
143			exp := got[len(before)+2*i+1]
144			if refund.Kind != LedgerRefund || refund.AccountID != "payer" ||
145				refund.RequestID != e.request || refund.Amount != e.amount ||
146				!refund.At.Equal(e.at) || refund.Reason == "" {
147				t.Fatalf("refund entry %d = %+v, want payer refund of %d for %s at %v",
148					i, refund, e.amount, e.request, e.at)
149			}
150			if exp.Kind != LedgerReservationExpiration || exp.AccountID != e.account ||
151				exp.RequestID != e.request || exp.Amount != 0 ||
152				!exp.At.Equal(e.at) || exp.Reason == "" {
153				t.Fatalf("expiration entry %d = %+v, want zero-amount timeout for %s/%s at %v",
154					i, exp, e.account, e.request, e.at)
155			}
156			refundSum += refund.Amount
157		}
158		if refundSum != 136 {
159			t.Fatalf("refund sum = %d, want 136", refundSum)
160		}
161	
162		// 退款合计与查询前后的余额变化对上：854 + 136 = 990，未到期 r3 仍占 10。
163		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 990, Reserved: 10}) {
164			t.Fatalf("balance after query = %+v, want {990 10}", bal)
165		}
166		// 各策略预留总额减少同样金额，已花费总额不增加。
167		for id, totals := range map[string][2]int64{
168			"pa": {0, 0}, "pb": {10, 0}, "pc": {0, 0}, "pd": {0, 0},
169		} {
170			pv, err := w.Policy(id)
171			if err != nil {
172				t.Fatal(err)
173			}
174			if pv.ReservedTotal != totals[0] || pv.SpentTotal != totals[1] {
175				t.Fatalf("policy %s totals = reserved %d spent %d, want %d/%d",
176					id, pv.ReservedTotal, pv.SpentTotal, totals[0], totals[1])
177			}
178		}
179	
180		// 各请求（含同号不同账户）分别进入预留超时终态：释放时间为自己的截止
181		// 时刻，实际费用为零。
182		for _, e := range want {
183			req, err := w.Request(e.account, e.request)
184			if err != nil {
185				t.Fatal(err)
186			}
187			if req.State != RequestReservationExpired ||
188				!req.ReserveDeadline.Equal(e.at) || !req.ReserveExpiredAt.Equal(e.at) ||
189				req.ActualFee != 0 {
