191					e.account, e.request, req, e.at)
192			}
193		}
194	
195		// 截止时刻晚于查询时刻的 r3 继续预留：不产生退款或超时记录。
196		req, _ := w.Request("u1", "r3")
197		if req.State != RequestReserved || !req.ReserveExpiredAt.IsZero() {
198			t.Fatalf("r3 = %+v, want still reserved", req)
199		}
200		for _, e := range got {
201			if e.RequestID == "r3" && e.Kind != LedgerReserve {
202				t.Fatalf("r3 produced early release entry: %+v", e)
203			}
204		}
205	
206		// 很久之后才再次查询：r3 的释放时间仍是它原来的截止时刻 t0+34 而非
207		// 查询时刻，新记录继续追加在末尾，不重排旧账本。
208		c.t = t0.Add(40 * time.Second)
209		again := w.Ledger()
210		if len(again) != len(got)+2 {
211			t.Fatalf("ledger after second query = %d entries, want %d", len(again), len(got)+2)
212		}
213		if !reflect.DeepEqual(again[:len(got)], got) {
214			t.Fatal("second query rewrote existing ledger entries")
215		}
216		tail := again[len(got):]
217		if tail[0].Kind != LedgerRefund || tail[0].AccountID != "payer" ||
218			tail[0].RequestID != "r3" || tail[0].Amount != 10 ||
219			!tail[0].At.Equal(t0.Add(34*time.Second)) || tail[0].Reason == "" {
220			t.Fatalf("r3 refund = %+v, want payer refund of 10 at t0+34s", tail[0])
221		}
222		if tail[1].Kind != LedgerReservationExpiration || tail[1].AccountID != "u1" ||
223			tail[1].RequestID != "r3" || tail[1].Amount != 0 ||
224			!tail[1].At.Equal(t0.Add(34*time.Second)) || tail[1].Reason == "" {
225			t.Fatalf("r3 expiration = %+v, want zero-amount timeout at t0+34s", tail[1])
226		}
227		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 1000, Reserved: 0}) {
228			t.Fatalf("final balance = %+v, want {1000 0}", bal)
229		}
230		if pv, _ := w.Policy("pb"); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
231			t.Fatalf("pb totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
232		}
233	}
234	
235	// 同一请求编号分属不同使用账户、截止时刻相同：一次余额查询触发后两笔分别
236	// 释放、按使用账户升序留痕，互不合并或替代；未到期请求继续占用余额与策略
237	// 共享额度。
238	func TestMultiReservationTimeoutBalanceQuotaAndSameID(t *testing.T) {
239		w, c := setupMultiTimeout(t)
240		pa := multiTimeoutPolicy(c, "pa", 10*time.Second)
241		pa.MaxPerRequest, pa.MaxTotal = 50, 50
242		if err := w.SavePolicy(pa); err != nil {
243			t.Fatal(err)
244		}
245		pb := multiTimeoutPolicy(c, "pb", time.Hour)
246		pb.MaxPerRequest, pb.MaxTotal = 40, 40
247		if err := w.SavePolicy(pb); err != nil {
248			t.Fatal(err)
249		}
250	
251		t0 := c.t
252		applyMulti(t, w, "pa", "u2", "r1", 20) // 截止 t0+10
253		applyMulti(t, w, "pa", "u1", "r1", 20) // 截止 t0+10：同号同截止，分属 u1/u2
254		applyMulti(t, w, "pb", "u1", "r2", 30) // 截止 t0+1h：继续预留
255	
256		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 930, Reserved: 70}) {
257			t.Fatalf("balance = %+v, want {930 70}", bal)
258		}
259	
260		// 恰为两笔 r1 的截止时刻：到达截止时刻本身就释放；用余额查询触发，
261		// 退款合计 40 与余额变化对上。
262		c.t = t0.Add(10 * time.Second)
263		bal, err := w.Balance("payer")
264		if err != nil {
265			t.Fatal(err)
266		}
267		if bal != (Balances{Available: 970, Reserved: 30}) {
268			t.Fatalf("balance after expiry = %+v, want {970 30} (refund 40 = delta)", bal)
269		}
270	
271		// 同截止时刻按使用账户升序：u1/r1 的两条记录在前，u2/r1 的在后，
272		// 两笔同号请求各自成对出现，不被合并。
273		ledger := w.Ledger()
274		if len(ledger) != 7 {
275			t.Fatalf("ledger = %d entries, want 7", len(ledger))
276		}
277		newEntries := ledger[3:]
278		for i, acc := range []string{"u1", "u2"} {
279			refund, exp := newEntries[2*i], newEntries[2*i+1]
280			if refund.Kind != LedgerRefund || refund.AccountID != "payer" ||
281				refund.RequestID != "r1" || refund.Amount != 20 ||
282				!refund.At.Equal(t0.Add(10*time.Second)) || refund.Reason == "" {
283				t.Fatalf("refund %d = %+v, want payer refund of 20 for r1 at deadline", i, refund)
284			}
285			if exp.Kind != LedgerReservationExpiration || exp.AccountID != acc ||
286				exp.RequestID != "r1" || exp.Amount != 0 ||
287				!exp.At.Equal(t0.Add(10*time.Second)) || exp.Reason == "" {
288				t.Fatalf("expiration %d = %+v, want zero-amount timeout for %s/r1", i, exp, acc)
289			}
290		}
291		for _, acc := range []string{"u1", "u2"} {
292			req, _ := w.Request(acc, "r1")
293			if req.State != RequestReservationExpired || req.ActualFee != 0 {
294				t.Fatalf("%s/r1 = %+v, want reservation expired with zero actual fee", acc, req)
295			}
296		}
297	
298		// 未到期的 r2 继续预留：金额仍占用余额与策略共享额度（pb 已用 30/40）。
299		if r2, _ := w.Request("u1", "r2"); r2.State != RequestReserved {
300			t.Fatalf("r2 state = %v, want reserved", r2.State)
301		}
302		if pv, _ := w.Policy("pb"); pv.ReservedTotal != 30 {
303			t.Fatalf("pb reserved = %d, want 30 (r2 still holds quota)", pv.ReservedTotal)
304		}
305		over := baseApply()
306		over.PolicyID, over.RequestID, over.EstimatedFee = "pb", "r3", 11
307		if _, err := w.Apply(over); !errors.Is(err, ErrQuotaExceeded) {
308			t.Fatalf("apply over quota err = %v, want ErrQuotaExceeded", err)
309		}
310		// 额度内的申请正常受理。
311		ok := baseApply()
312		ok.PolicyID, ok.RequestID, ok.EstimatedFee = "pb", "r4", 10
313		if _, err := w.Apply(ok); err != nil {
314			t.Fatalf("apply within quota: %v", err)
315		}
316		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 960, Reserved: 40}) {
317			t.Fatalf("final balance = %+v, want {960 40}", bal)
318		}
319	}
