790			wg.Wait()
791	
792			req, _ := w.Request("u1", fmt.Sprintf("race-%d", iter))
793			if req.State != RequestReservationExpired {
794				t.Fatalf("iter %d: state = %v, want reservation expired", iter, req.State)
795			}
796			// 退款只能发生一次，超时留痕只能一条。
797			if n := countKind(w.Ledger(), LedgerRefund); n != 1 {
798				t.Fatalf("iter %d: refund entries = %d, want 1", iter, n)
799			}
800			if n := countKind(w.Ledger(), LedgerReservationExpiration); n != 1 {
801				t.Fatalf("iter %d: timeout entries = %d, want 1", iter, n)
802			}
803			if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
804				t.Fatalf("iter %d: balance = %+v", iter, bal)
805			}
806			pv, _ := w.Policy("p-timeout")
807			if pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
808				t.Fatalf("iter %d: totals = %+v", iter, pv)
809			}
810		}
811	}
