813	func TestTimeoutRefundedMoneyReusedLateSettleBlocked(t *testing.T) {
814		w, c := setupTimeout(t, 30*time.Second)
815		if _, err := w.Apply(timeoutApply()); err != nil {
816			t.Fatal(err)
817		}
818		c.t = c.t.Add(30 * time.Second)
819		// 仅凭余额查询触发释放，随后新申请立即把退回的费用重新预留。
820		if _, err := w.Balance("payer"); err != nil {
821			t.Fatal(err)
822		}
823		next := timeoutApply()
824		next.RequestID = "r2"
825		if _, err := w.Apply(next); err != nil {
826			t.Fatal(err)
827		}
828		// 迟到结算旧请求：超时错误，不能扣走已被 r2 使用的费用。
829		if _, err := w.Settle("u1", "r1", 20); !errors.Is(err, ErrReservationExpired) {
830			t.Fatalf("late settle err = %v, want ErrReservationExpired", err)
831		}
